CREATE TABLE fertilizer_applications(`id` bigint  UNSIGNED PRIMARY KEY AUTO_INCREMENT,`created_at` timestamp  DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` timestamp  DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP NOT NULL,`enable` TINYINT(1)  NOT NULL  DEFAULT 1 ,`farm_id` bigint  NOT NULL,`plot_id` bigint  NULL COMMENT 'Optional specific plot',`crop_id` bigint  NULL COMMENT 'Associated crop if applicable',`application_date` date  NOT NULL COMMENT 'Date of fertilizer application',`fertilizer_type` varchar(100)  NOT NULL COMMENT 'Type: urea, dap, mop, vermicompost, etc.',`category` varchar(50)  NOT NULL COMMENT 'Category: organic or chemical',`quantity_kg` DECIMAL(10,2)  NOT NULL COMMENT 'Total quantity applied (kg)',`quantity_per_hectare` DECIMAL(10,2)  NULL COMMENT 'Quantity per hectare (kg/ha)',`area_applied_hectares` DECIMAL(10,2)  NULL COMMENT 'Area where fertilizer was applied',`nitrogen_kg` DECIMAL(10,2)  NULL COMMENT 'Nitrogen provided (kg)',`phosphorus_kg` DECIMAL(10,2)  NULL COMMENT 'Phosphorus provided (kg)',`potassium_kg` DECIMAL(10,2)  NULL COMMENT 'Potassium provided (kg)',`cost_total` DECIMAL(10,2)  NULL COMMENT 'Total cost (₹)',`cost_per_kg` DECIMAL(10,2)  NULL COMMENT 'Cost per kg (₹)',`cost_per_hectare` DECIMAL(10,2)  NULL COMMENT 'Cost per hectare (₹)',`application_method` varchar(255)  NULL COMMENT 'Method: broadcast, banding, foliar, etc.',`growth_stage` varchar(100)  NULL COMMENT 'Crop growth stage: basal, vegetative, flowering',`days_after_planting` bigint  NULL COMMENT 'Days after planting when applied',`soil_test_before_id` bigint  NULL COMMENT 'Soil test before application',`soil_test_after_id` bigint  NULL COMMENT 'Soil test after application',`effectiveness_score` DECIMAL(5,2)  NULL COMMENT 'Effectiveness score (0-100) based on soil response',`soil_response_notes` text  NULL COMMENT 'Observed soil response and crop performance',`weather_conditions` varchar(255)  NULL COMMENT 'Weather during application',`temperature_celsius` DECIMAL(5,2)  NULL COMMENT 'Temperature during application',`rainfall_mm_24h` DECIMAL(6,2)  NULL COMMENT 'Rainfall within 24 hours after application',`recommended_by` varchar(255)  NULL COMMENT 'Source: system, agronomist, farmer',`recommendation_id` varchar(255)  NULL COMMENT 'Reference to recommendation that suggested this',`notes` text  NULL COMMENT 'Additional notes')ENGINE = InnoDB AUTO_INCREMENT = 1 DEFAULT CHARSET = utf8;